Import ListNotations.
Open Scope bv_scope.
Open Scope Z_scope.
#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_n8 segs m a bs.
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.

Section LOOP8.
  Context {HCEIL : HeapCeil}.
  Variables (ra sp gp tp t1 t2 s0 s1 a1 a6 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem) (FB : Z) (FV : Z -> Z).
  Hypothesis FL : forall pos, 0 <= pos < 64 -> rw_cells asegs m (FB + pos) [C1 (b8 (FV pos))].
  Hypothesis FV01 : forall pos, FV pos = 0 \/ FV pos = 1.

  Definition loop8_post : machine_state -> Prop :=
    fun ms' => exists (cur' t0 : word) (c' p : Z),
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 c') a1 cur' (Z_to_bv 64 (FB + p)) (Z_to_bv 64 FB) (Z_to_bv 64 63) a6 (Z_to_bv 64 p)
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 0x9e980) fc None m (seg_rom asegs)
      /\ 0 <= p < 64 /\ p = bv_unsigned cur' mod 64 /\ FV p = 0 /\ 1 <= c' <= 64.

  Lemma sm8_loop : forall (n : nat) (cur a3 a7 t0 : word) (c : Z),
    c = Z.of_nat n -> 1 <= c <= 64 ->
    (exists j, 0 <= j < c /\ FV ((bv_unsigned cur + j) mod 64) = 0) ->
    evt asegs loop8_post
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 c) a1 cur a3 (Z_to_bv 64 FB) (Z_to_bv 64 63) a6 a7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 0x9e934) fc None m (seg_rom asegs)).
Proof.
