Section FOUND8.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis RFS_is : forall LF m, as_RFS H LF m <-> RFSI (as_FSB H) LF m.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
            (m m2 : mem) (LF : list fframe) (lo p c' sz : Z) (rax t0 t1 t2 cur a6 t3 t4 t5 t6 : word) (jpad : list byte).
  Hypothesis FR : rw_cells asegs m2 (bv_unsigned sp + -48) [CB 8 jpad; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].
  Hypothesis ST0 : stk asegs m2 lo (bv_unsigned sp + -48).
  Hypothesis LO : aceil <= lo.
  Hypothesis LOSP : lo <= bv_unsigned sp - 1024.
  Hypothesis MI : mem_inv asegs m2.
  Hypothesis AC : ACONST m2.
  Hypothesis R : RFSI (as_FSB H) LF m2.
  Hypothesis HP : 0 <= p < 64.
  Hypothesis FREE : flagv LF (flag_addr (as_FSB H) 8 p) = 0.
  Hypothesis MU0 : munch [(bv_unsigned sp - 1024, bv_unsigned sp)] m m2.
  Hypothesis WM0 : wmono asegs m m2.
  Hypothesis SZ : 0 < sz <= 16384.
  Hypothesis SZ8 : sz mod 8 = 0.

  Lemma sm8_found :
    evt asegs (stack_malloc_sz_post H 8 ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF lo sz m)
      (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 sp (Z_to_bv 64 sz)
               (Z_to_bv 64 c') (Z_to_bv 64 (as_FSB H + 4096)) cur (Z_to_bv 64 (as_FSB H + 36736 + p)) (Z_to_bv 64 (as_FSB H + 36736)) (Z_to_bv 64 63) a6 (Z_to_bv 64 p)
               (Z_to_bv 64 (as_FSB H)) (Z_to_bv 64 20) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
